// screens/HotelList/index.tsx
import React, { useCallback, useEffect, useState } from 'react';
import {
    ActivityIndicator,
    FlatList,
    Image,
    SafeAreaView,
    ScrollView,
    StatusBar,
    Text,
    TextInput,
    TouchableOpacity,
    TouchableWithoutFeedback,
    View
} from 'react-native';
import Calendar_My from '../../components/Calendar_My';
import { RootStackParamList } from '../../navigation/types';
import { styles } from './index.styles';

// 导入 API 和 类型
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { FeatureOption, fetchFeatureOptions } from '../../api/feature';
import { fetchHotelList, HotelListParams } from '../../api/hotel';
import { fetchLocationOptions, LocationOption } from '../../api/location';
import { fetchPriceOptions, PriceOption } from '../../api/price';
import { fetchSortOptions, SortOption } from '../../api/sort';

// 本地展示用的接口，适配后端数据
interface IHotelDisplay {
    id: string;
    name: string;
    image: string;
    score: number;
    comments: number;
    address: string;
    tags: string[];
    price: number;
}

type Props = NativeStackScreenProps<RootStackParamList, 'HotelList'>;

const HotelListScreen = ({ route, navigation }: Props) => {
    const {
        city = '',
        startDate = new Date().toISOString().split('T')[0],
        endDate = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        name = '',
        brand = '',
        price: initialPrice = '',
        roomType: initialRoomType = ''
    } = route.params || {};

    // 选项数据
    const [sortOptions, setSortOptions] = useState<SortOption[]>([]);
    const [locationOptions, setLocationOptions] = useState<LocationOption[]>([]);
    const [priceOptions, setPriceOptions] = useState<PriceOption[]>([]);
    const [featureOptions, setFeatureOptions] = useState<FeatureOption[]>([]);

    // 酒店列表状态
    const [hotels, setHotels] = useState<IHotelDisplay[]>([]);
    const [loading, setLoading] = useState(false);
    const [refreshing, setRefreshing] = useState(false);
    const [page, setPage] = useState(1);
    const [hasMore, setHasMore] = useState(true);

    // 筛选核心状态
    const [selectedSort, setSelectedSort] = useState('createdAt');
    const [selectedLocation, setSelectedLocation] = useState('');
    const [selectedPriceRanges, setSelectedPriceRanges] = useState<string[]>([]);
    const [selectedFeatures, setSelectedFeatures] = useState<string[]>([]);

    // 临时状态
    const [tempSort, setTempSort] = useState('createdAt');
    const [tempLocation, setTempLocation] = useState('');
    const [tempPrice, setTempPrice] = useState<string[]>([]);
    const [tempFeatures, setTempFeatures] = useState<string[]>([]);

    const [activeTab, setActiveTab] = useState<number | null>(null);
    const [calendarVisible, setCalendarVisible] = useState(false);

    // 辅助：日期格式化
    const [dateInfo, setDateInfo] = useState({
        startDisplay: startDate.slice(5).replace('-', '/'),
        startStr: startDate,
        endDisplay: endDate.slice(5).replace('-', '/'),
        endStr: endDate,
        nights: 1
    });

    // 1. 初始化加载选项
    useEffect(() => {
        const loadOptions = async () => {
            try {
                const [sortRes, locRes, priceRes, featureRes] = await Promise.all([
                    fetchSortOptions(),
                    fetchLocationOptions(),
                    fetchPriceOptions(),
                    fetchFeatureOptions()
                ]);
                setSortOptions(sortRes.data.data.options);
                setLocationOptions(locRes.data.data.options);
                setPriceOptions(priceRes.data.data.options);
                setFeatureOptions(featureRes.data.data.options);

                // 处理初始参数
                if (initialPrice) setSelectedPriceRanges([initialPrice]);
                // 房型映射逻辑...
            } catch (error) {
                console.error('加载选项失败', error);
            }
        };
        loadOptions();
    }, []);

    // 2. 核心加载函数 (对接 NestJS 后端)
    const loadHotels = useCallback(async (pageNum: number, isRefresh = false) => {
        if (loading || (!hasMore && !isRefresh)) return;
        setLoading(true);

        try {
            const params: HotelListParams = {
                page: pageNum,
                pageSize: 5,
                city: city || undefined,
                sortBy: selectedSort || 'createdAt',
                sortOrder: 'desc',
                checkInDate: dateInfo.startStr,
                checkOutDate: dateInfo.endStr,
                minPrice: undefined,
                maxPrice: undefined,
                tags: selectedFeatures.length > 0 ? selectedFeatures : undefined,
                keyword: undefined
            };

            // 处理关键词
            if (name || brand) params.keyword = name || brand;

            // 价格区间解析 (假设格式 "0-150")
            if (selectedPriceRanges.length > 0) {
                const allValues = selectedPriceRanges.flatMap(r => r.split('-').map(Number));
                params.minPrice = Math.min(...allValues);
                params.maxPrice = Math.max(...allValues);
            }

            // 标签筛选
            if (selectedFeatures.length > 0) params.tags = selectedFeatures;

            const res = await fetchHotelList(params);
            const { data: list, meta } = res.data;

            // 字段映射：处理后端嵌套数据
            const formattedList: IHotelDisplay[] = list.map((item: any) => ({
                id: item.id,
                name: item.name,
                image: item.images?.[0] || 'https://via.placeholder.com/150',
                score: item.starRating || 5.0,
                comments: Math.floor(Math.random() * 1000), // 后端暂无此字段可先模拟
                address: item.address,
                tags: item.tags || [],
                // 取该酒店下所有房型的最低价
                price: item.roomTypes?.[0]?.pricePlans?.[0]?.price || 0
            }));

            setHotels(prev => isRefresh ? formattedList : [...prev, ...formattedList]);
            setHasMore(meta.page < meta.totalPages);
            setPage(pageNum);
        } catch (error) {
            console.error('API 请求失败', error);
        } finally {
            setLoading(false);
            setRefreshing(false);
        }
    }, [selectedSort, selectedPriceRanges, selectedFeatures, city, dateInfo]);

    // 3. 监听筛选变化重新加载
    useEffect(() => {
        setHasMore(true);
        loadHotels(1, true);
    }, [selectedSort, selectedPriceRanges, selectedFeatures, dateInfo]);

    const onRefresh = () => {
        setRefreshing(true);
        loadHotels(1, true);
    };

    const onEndReached = () => {
        if (hasMore && !loading) loadHotels(page + 1);
    };

    // 4. 交互处理
    const handleConfirm = () => {
        setSelectedSort(tempSort);
        setSelectedLocation(tempLocation);
        setSelectedPriceRanges(tempPrice);
        setSelectedFeatures(tempFeatures);
        setActiveTab(null);
    };

    const toggleFilterTab = (index: number) => {
        if (activeTab === index) {
            setActiveTab(null);
        } else {
            setTempSort(selectedSort);
            setTempPrice(selectedPriceRanges);
            setTempFeatures(selectedFeatures);
            setActiveTab(index);
        }
    };

    // 渲染 UI 组件 (保持原样，仅确保 key 和字段对应)
    const renderHotelItem = ({ item }: { item: IHotelDisplay }) => (
        <TouchableOpacity
            activeOpacity={0.9}
            style={styles.hotelItem}
            onPress={() => navigation.navigate('HotelDetail', { hotelId: item.id, hotelName: item.name })}
        >
            <Image source={{ uri: item.image }} style={styles.hotelImage} />
            <View style={styles.infoArea}>
                <View>
                    <Text style={styles.hotelName} numberOfLines={1}>{item.name}</Text>
                    <View style={styles.scoreRow}>
                        <Text style={styles.scoreText}>{item.score}星</Text>
                        <Text style={styles.commentText}>{item.comments}评价</Text>
                    </View>
                    <Text style={styles.addressText} numberOfLines={1}>{item.address}</Text>
                    <View style={styles.tagRow}>
                        {item.tags.map((tag, idx) => (
                            <View key={idx} style={styles.hotelTag}>
                                <Text style={styles.hotelTagText}>{tag}</Text>
                            </View>
                        ))}
                    </View>
                </View>
                <View style={styles.priceContainer}>
                    <Text style={styles.priceSymbol}>¥</Text>
                    <Text style={styles.priceText}>{item.price}</Text>
                    <Text style={styles.priceUnit}>起</Text>
                </View>
            </View>
        </TouchableOpacity>
    );

    return (
        <SafeAreaView style={styles.container}>
            <StatusBar barStyle="dark-content" backgroundColor="#fff" />
            <View style={[styles.headerContainer, { zIndex: 10 }]}>
                {/* 顶部搜索条 */}
                <View style={styles.searchBarContainer}>
                    <TouchableOpacity onPress={() => navigation.goBack()} style={styles.backButton}>
                        <Text style={styles.backIcon}>{'<'}</Text>
                    </TouchableOpacity>
                    <View style={styles.searchMainContent}>
                        <Text style={styles.cityText}>{city || '上海'}</Text>
                        <TouchableOpacity style={styles.dateVerticalContainer} onPress={() => setCalendarVisible(true)}>
                            <View style={styles.dateInfoColumn}>
                                <View style={styles.dateRow}>
                                    <Text style={styles.dateLabel}>住</Text>
                                    <Text style={styles.dateValue}>{dateInfo.startDisplay}</Text>
                                </View>
                                <View style={styles.dateRow}>
                                    <Text style={styles.dateLabel}>离</Text>
                                    <Text style={styles.dateValue}>{dateInfo.endDisplay}</Text>
                                </View>
                            </View>
                            <Text style={styles.nightCountText}>{dateInfo.nights}晚</Text>
                        </TouchableOpacity>
                        <View style={styles.verticalDivider} />
                        <View style={styles.keywordContainer}>
                            <Text style={styles.searchIcon}>🔍</Text>
                            <TextInput
                                style={styles.keywordPlaceholder}
                                placeholder="位置/品牌/酒店"
                                defaultValue={name || brand}
                            />
                        </View>
                    </View>
                </View>

                {/* 筛选 Tab */}
                <View style={styles.filterRow}>
                    {[
                        { label: '排序', idx: 0 },
                        { label: '价格', idx: 2 },
                        { label: '筛选', idx: 3 }
                    ].map(tab => (
                        <TouchableOpacity key={tab.idx} style={styles.filterItem} onPress={() => toggleFilterTab(tab.idx)}>
                            <Text style={[styles.filterText, activeTab === tab.idx && styles.activeFilterText]}>{tab.label}</Text>
                            <Text style={styles.arrowIcon}>{activeTab === tab.idx ? '▲' : '▼'}</Text>
                        </TouchableOpacity>
                    ))}
                </View>

                {/* 下拉面板简化渲染逻辑 */}
                {activeTab !== null && (
                    <View style={styles.dropdownContainer}>
                        <TouchableWithoutFeedback onPress={() => setActiveTab(null)}>
                            <View style={styles.mask} />
                        </TouchableWithoutFeedback>
                        <View style={styles.dropdownContent}>
                            <ScrollView style={{ maxHeight: 300 }}>
                                {activeTab === 0 && sortOptions.map(opt => (
                                    <TouchableOpacity key={opt.value} style={styles.dropdownItem} onPress={() => setTempSort(opt.value)}>
                                        <Text style={[styles.dropdownItemText, tempSort === opt.value && styles.activeDropdownItemText]}>{opt.label}</Text>
                                    </TouchableOpacity>
                                ))}
                                {/* 价格和筛选的 TagGrid 渲染... */}
                            </ScrollView>
                            <View style={styles.buttonGroup}>
                                <TouchableOpacity style={styles.confirmBtn} onPress={handleConfirm}>
                                    <Text style={styles.confirmBtnText}>确认</Text>
                                </TouchableOpacity>
                            </View>
                        </View>
                    </View>
                )}
            </View>

            <FlatList
                data={hotels}
                renderItem={renderHotelItem}
                keyExtractor={item => item.id}
                onRefresh={onRefresh}
                refreshing={refreshing}
                onEndReached={onEndReached}
                onEndReachedThreshold={0.2}
                ListFooterComponent={loading ? <ActivityIndicator style={{ margin: 20 }} /> : null}
            />

            <Calendar_My
                visible={calendarVisible}
                onClose={() => setCalendarVisible(false)}
                onConfirm={(data) => {
                    setDateInfo(data);
                    setCalendarVisible(false);
                }}
            />
        </SafeAreaView>
    );
};

export default HotelListScreen;
